const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Arrachart is a small locality in Madagascar, using approximate coordinates
  // Near the central-eastern region of Madagascar
  const point = ee.Geometry.Point([47.5, -19.0]);

  // January 2020
  const startDate = '2020-01-01';
  const endDate = '2020-02-01';

  // CHIRPS daily precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(point);

  const imageCount = chirps.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No precipitation data found for January 2020.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Sum all daily precipitation for the month
  const totalPrecip = chirps.sum();

  // Calculate total precipitation at the point
  const precipStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: point,
    scale: 5000,
    maxPixels: 1e9
  });

  const precipValue = precipStats.get('precipitation').getInfo();

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels found.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (precipValue === null || precipValue === undefined || isNaN(precipValue)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert 22 inches to mm: 22 * 25.4 = 558.8 mm
  const thresholdMm = 22 * 25.4;
  const precipInches = precipValue / 25.4;

  console.log(`Total rainfall: ${precipValue.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${thresholdMm.toFixed(2)} mm (22 inches)`);

  if (precipValue > thresholdMm) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
